UPDATE plantilla SET contenido_html = '<p style="text-align:center"><strong>Ref. Legajo </strong><strong>N°</strong><strong> [</strong><strong>Acta:Expediente</strong><strong>]  -</strong><strong>  Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong></p><p style="text-align:center"><strong><u>Movimientos</u></strong></p><p>[System:FECHA]:</p>' WHERE codigo = 'HOJA_DE_RUTA';
UPDATE plantilla SET contenido_html = '<p style="text-align:right">Los Polvorines, [System:TEXTOFECHA]</p><p style="text-align:justify"><strong>DE: DIRECCIÓN DE FALTAS</strong></p><p style="text-align:justify"><strong>A: JUZGADO DE PAZ LETRADO – MALVINAS ARGENTINAS</strong></p><p style="text-align:justify"><strong>S____________________/____________________D</strong></p><p style="text-align:justify">Por medio de la presente me dirijo a Ud. en mi carácter de Directora de Faltas de la Municipalidad de Malvinas Argentinas, a fin de remitir las actuaciones labradas con relación al <strong>Acta de Infracción/Contravención </strong><strong>N°</strong><strong> ………</strong> de fecha ….. de …………de 202.., conforme <strong>RESOLUCIÓN </strong><strong>N°</strong><strong> …</strong><strong>…….</strong><strong>. </strong>de fecha ………</p><p style="text-align:justify">Sin otro particular, saluda atentamente. -</p><p style="text-align:center"><strong>DF</strong></p><p style="text-align:center"><strong>Dra. María Elena Vivoda</strong></p><p style="text-align:center"><strong>Directora de Faltas</strong></p><p style="text-align:center"><strong>Municipalidad de Malvinas Argentinas</strong></p>' WHERE codigo = 'JUZGADO_DE_PAZ';
UPDATE plantilla SET contenido_html = '<p style="text-align:center"><strong><u>CÉDULA DE NOTIFICACIÓN DE RESOLUCIÓN</u></strong></p><p><strong>Señor/a:</strong><strong>   </strong>[Acta:Titular]</p><p><strong>Domicilio:</strong>   [Acta:Calle]   <strong>Nº</strong><strong>   </strong>[Acta:Nro.Puerta]</p><p><strong>Localidad / Partido:</strong><strong>   </strong>[Acta:Localidad]   /   [Acta:Partido]   <strong>Provincia:</strong><strong>   </strong>[Acta:Provincia.Infractor]</p><p><strong>Acta de Infracción </strong><strong>Nº</strong><strong>   [</strong><strong>Acta:Numero</strong><strong>]      Legajo </strong><strong>N</strong><strong>°</strong><strong>  [</strong><strong>Acta:Expediente</strong><strong>]</strong></p><p><strong>Repartición Actuante:   </strong>SUBSECRETARÍA DE TRÁNSITO Y BROMATOLOGÍA</p><p><strong>Objeto:</strong></p><p style="text-align:justify">Notifico a Ud., por medio de la presente cédula que se adjunta copia de la <strong>Resolución </strong><strong>N°</strong><strong>…… </strong>dictada con relación al <strong>Acta de Infracción </strong><strong>Nº</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong> que tramita ante la Dirección de Faltas. -</p><p style="text-align:center"><strong>QUEDA UD. DEBIDAMENTE NOTIFICADO/A</strong></p><p style="text-align:center"><strong>Dra. María Elena </strong><strong>Vivoda</strong></p><p style="text-align:center"><strong>Directora de Faltas</strong></p><p style="text-align:center"><strong>Municipalidad de Malvinas Argentinas</strong></p>' WHERE codigo = 'NOT_DE_RESOLUCION_TRANSITO';
UPDATE plantilla SET contenido_html = '<p style="text-align:right">Los Polvorines, [System:TEXTOFECHA]</p><p style="text-align:right"><strong>Ref. Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>] </strong></p><p><strong>DE: DIRECCIÓN DE FALTAS</strong></p><p style="text-align:justify"><strong>A: DIRECCIÓN DE ASUNTOS LEGALES</strong></p><p style="text-align:justify">Me dirijo a Usted con relación al <strong>Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>] </strong>de fecha [Acta:Fecha] labrada en [Acta:Calle.Infraccion] de la ciudad de [Acta:Localidad_Infraccion], ocasión en la que el funcionario de tránsito interviniente en operativo de control vehicular constató que el <strong>Sr. [</strong><strong>Acta:Titular</strong><strong>], DNI </strong><strong>N°</strong><strong> [</strong><strong>Acta:Nro.Documento</strong><strong>], </strong>a bordo del vehículo <strong>marca [</strong><strong>Acta:Actividad</strong><strong>] modelo [</strong><strong>Acta:Actividad</strong><strong>] dominio [</strong><strong>Acta:Dominio.Vehiculo</strong><strong>] </strong>circulaba con licencia de conducir presuntamente apócrifa.</p><p style="text-align:justify">En virtud de lo expuesto anteriormente, y teniendo presente las prescripciones del Art. 287 del C.P.P. de la provincia de Buenos Aires, solicito a Ud. arbitre los medios necesarios a los efectos de realizar la denuncia penal. A tal efecto, acompaño copia certificada del <strong>Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong> así como también el instrumento apócrifo original a los fines pertinentes. -</p><p style="text-align:center"><strong>DF</strong></p><p style="text-align:center"><strong>Dra. María Elena </strong><strong>Vivoda</strong></p><p style="text-align:center"><strong>Directora de Faltas</strong></p><p style="text-align:center"><strong>Municipalidad de Malvinas Argentinas</strong></p>' WHERE codigo = 'NOTA_A_LEGALES_DOC_APOCRIFA';
UPDATE plantilla SET contenido_html = '<p style="text-align:right">Los Polvorines, [System:TEXTOFECHA]</p><p style="text-align:right"><strong>Ref.: Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong></p><p style="text-align:right"><strong>Infractor: [</strong><strong>Acta:Titular</strong><strong>]</strong></p><p style="text-align:justify"><strong>DE: DIRECCIÓN A FALTAS</strong></p><p style="text-align:justify"><strong>A: DIRECCIÓN GENERAL DE SEGURIDAD VIAL Y TRANSPORTE</strong></p><p style="text-align:justify">Tengo el agrado de dirigirme a Ud. con relación al acta de la referencia atento en el día de la fecha se dictó la <strong>DISPOSICIÓN DE LEVANTAMIENTO DE SECUESTRO </strong><strong>N°</strong><strong> _____________ </strong>correspondiente al <strong>Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>] – Dominio [</strong><strong>Acta:Dominio.Vehiculo</strong><strong>]</strong>. Sin embargo, de los registros obrantes en la dependencia a mi cargo se constató que medió error involuntario al asignarse el número de disposición mencionado anteriormente toda vez que ya había sido asignado a otro acto administrativo.</p><p style="text-align:justify">Por ello, en este acto informo a Ud. que el número correcto resulta ser _____, Acompaño copia certificada de <strong>DISPOSICIÓN LEVANTAMIENTO DE SECUESTRO </strong><strong>N°</strong><strong> ____________. -</strong></p><p style="text-align:center"><strong>DF</strong></p><p style="text-align:center"><strong>Dra. María Elena </strong><strong>Vivoda</strong></p><p style="text-align:center"><strong>Directora de Faltas</strong></p><p style="text-align:center"><strong>Municipalidad de Malvinas Argentinas</strong></p>' WHERE codigo = 'NOTA_A_SEG_VIAL_RECTIFICA_N_DE_DISP';
UPDATE plantilla SET contenido_html = '<p style="text-align:right"><strong>Ref.: Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>] </strong></p><p style="text-align:right"><strong>Legajo </strong><strong>N°</strong><strong> [</strong><strong>Acta:Expediente</strong><strong>] </strong></p><p style="text-align:justify">Por medio de la presente se deja constancia que bajo <strong>Expte</strong><strong>. Administrativo </strong><strong>N°</strong><strong> 4132-</strong> …………………. tramita <strong>AFECTACIÓN AL USO MUNICIPAL</strong> del motovehículo descripto en el acta de la referencia. Conste. -</p>' WHERE codigo = 'NOTA_AFECTACION_AL_USO_MUNICIPAL';
UPDATE plantilla SET contenido_html = '<p style="text-align:right">Los Polvorines, [System:TEXTOFECHA]</p><p style="text-align:center"><strong>Legajo </strong><strong>N°</strong><strong> [</strong><strong>Acta:Expediente</strong><strong>]</strong></p><p style="text-align:center"><strong>Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong></p><p style="text-align:justify">Por medio del presente se deja constancia que el presente legajo cuenta con antecedentes originados en <strong>Acta de Infracción </strong><strong>N°</strong><strong> ................. </strong>correspondiente a <strong>Legajo </strong><strong>N°</strong><strong> ................., </strong>siendo agregado al mismo en el día de la fecha.</p><p style="text-align:justify">Conste. -</p>' WHERE codigo = 'NOTA_ANTECEDENTES';
UPDATE plantilla SET contenido_html = '<p style="text-align:right"><strong>Ref.: ACTA </strong><strong>Nº</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong></p><p><strong>Señor</strong></p><p><strong>Jefe de Mesa Gral. De Entradas y Archivo</strong></p><p><strong>Don Gustavo D. HEGOBURU</strong></p><p style="text-align:justify"><strong><u>S</u></strong><strong><u>/</u></strong><strong><u>D </u></strong></p><p style="text-align:justify">Remito a Ud. las presentes actuaciones para que las mismas sean caratuladas como <strong>“[</strong><strong>Acta:Titular</strong><strong>] S/LIQUIDACIÓN DE DEUDA ACTA DE INFRACCIÓN </strong><strong>Nº</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]”</strong>.<strong> </strong>Cumplido, pase a la Subsecretaría de Gobierno y Monitoreo Institucional para su conocimiento y posterior remisión a la Dirección de Apremios para la prosecución del trámite. </p><p style="text-align:justify">Se hace saber que el contraventor suscribió compromiso de pago para abonar en ..... (.....) cuotas mensuales y consecutivas el Fallo Administrativo Nº ...... Sin embargo, al día de la fecha no se ha cumplimentado en debida forma la obligación de pago asumida por el Sr. …….. -</p><p style="text-align:center"><strong>DF</strong></p><p style="text-align:center"><strong>Dra. María Elena </strong><strong>Vivoda</strong></p><p style="text-align:center"><strong>Directora de Faltas</strong></p><p style="text-align:center"><strong>Municipalidad de Malvinas Argentinas</strong></p>' WHERE codigo = 'NOTA_APREMIOS_COMPR_DE_PAGO_NO_ABONO';
UPDATE plantilla SET contenido_html = '<p style="text-align:right"><strong>Ref.: ACTA </strong><strong>Nº</strong><strong> [</strong><strong>Acta:Numero</strong><strong>] </strong></p><p><strong>Señor</strong></p><p><strong>Jefe de Mesa Gral. De Entradas y Archivo</strong></p><p><strong>Don Gustavo D. HEGOBURU</strong></p><p style="text-align:justify"><strong><u>S</u></strong><strong><u>/</u></strong><strong><u>D</u></strong></p><p style="text-align:justify">Remito a Ud. las presentes actuaciones para que las mismas sean caratuladas como <strong>“[</strong><strong>Acta:Titular</strong><strong>] S/LIQUIDACIÓN DE DEUDA ACTA DE INFRACCIÓN </strong><strong>Nº</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]”</strong>.<strong> </strong>Cumplido, pase a la Subsecretaría de Gobierno y Monitoreo Institucional para su conocimiento y posterior remisión a la Dirección de Apremios para la prosecución del trámite.</p><p style="text-align:justify">Se hace saber que el contraventor suscribió un compromiso de pago para abonar en ....... cuotas mensuales y consecutivas el Fallo Administrativo Nº ......, acreditándose únicamente el pago de ...... (.....) cuotas, siendo la última en fecha ....... de ....... de 20.... -</p><p style="text-align:center"><strong>DF</strong></p><p style="text-align:center"><strong>Dra. María Elena </strong><strong>Vivoda</strong></p><p style="text-align:center"><strong>Directora de Faltas</strong></p><p style="text-align:center"><strong>Municipalidad de Malvinas Argentinas</strong></p>' WHERE codigo = 'NOTA_APREMIOS_CON_COMP_DE_PAGO_CUOTAS';
UPDATE plantilla SET contenido_html = '<p style="text-align:right">Los Polvorines, [System:TEXTOFECHA]<strong>Ref. ACTA </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong></p><p><strong>Señor</strong></p><p><strong>Jefe de Mesa Gral. De Entradas y Archivo</strong></p><p><strong>Don Gustavo D. HEGOBURU</strong></p><p style="text-align:justify"><strong><u>S</u></strong><strong><u>/</u></strong><strong><u>D </u></strong></p><p style="text-align:justify">Remito a Ud. las presentes actuaciones para que las mismas sean caratuladas como <strong>“[</strong><strong>Acta:Titular</strong><strong>] S/ LIQUIDACIÓN DE DEUDA ACTA DE INFRACCIÓN / CONTRAVENCIÓN </strong><strong>Nº</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]”. </strong>Cumplido, pase a la Subsecretaría de Gobierno Legal y Técnica para su conocimiento y posterior remisión a la Dirección de Apremios para la prosecución del trámite. -</p><p style="text-align:center"><strong>DF</strong></p><p style="text-align:center"><strong>Dra. María Elena </strong><strong>Vivoda</strong></p><p style="text-align:center"><strong>Directora de Faltas</strong></p><p style="text-align:center"><strong>Municipalidad de Malvinas Argentinas</strong></p>' WHERE codigo = 'NOTA_APREMIOS';
UPDATE plantilla SET contenido_html = '<p style="text-align:right">Los Polvorines, [System:TEXTOFECHA]</p><p style="text-align:right"><strong><u>Ref.</u></strong><strong> Legajo </strong><strong>N°</strong><strong> [</strong><strong>Acta:Expediente</strong><strong>] - Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong></p><p style="text-align:justify">En el día de la fecha, siendo las .......................... hs. por medio de la presente se deja expresa constancia que se hace entrega al <strong>Sr./Sra.  [</strong><strong>Acta:Titular</strong><strong>], D.N.I. </strong><strong>N°</strong><strong> [</strong><strong>Acta:Nro.Documento</strong><strong>]</strong>, la documentación que a continuación se detalla, a saber:</p><p style="text-align:justify">Licencia de conducir N° ………………. expedida por la Municipalidad de ……………………., con fecha de otorgamiento ……………… - fecha de vencimiento ……………….. .</p><p>Cédula de Identificación de Vehículos Control N° …………………………………………………………. </p><p style="text-align:justify">Déjese debida constancia en autos de su retiro. Fecho. Conste. -</p><p style="text-align:justify"><strong>Firma: __________________________________________________</strong></p><p style="text-align:justify"><strong>Aclaración: ______________________________________________</strong></p><p style="text-align:justify"><strong>D.N.I. </strong><strong>Nº</strong><strong>: _______________________________________________</strong></p><p style="text-align:justify"><strong>Teléfono de contacto: _____________________________________</strong></p><p><strong>Constituyo domicilio electrónico: ___________________________</strong></p>' WHERE codigo = 'NOTA_ENTREGA_DOC_LIC_Y_CED';
UPDATE plantilla SET contenido_html = '<p style="text-align:right">Los Polvorines, [System:TEXTOFECHA]</p><p style="text-align:right"><strong>Ref. Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong></p><p style="text-align:justify">Por medio de la presente, y atento la documentación acompañada por el <strong>Sr. [</strong><strong>Acta:Titular</strong><strong>], DNI </strong><strong>N°</strong><strong> [</strong><strong>Acta:Nro.Documento</strong><strong>], </strong>se deja expresa constancia que el interesado tiene la obligación legal de dar cumplimiento a las previsiones del Art. 34 de la Ley Nacional de Tránsito N° 24.449 y acompañar copia simple del <strong>CERTIFICADO DE OBLIGACIÓN TÉCNICA VEHICULAR</strong>, con resultado <strong>APTO</strong> o <strong>CONDICIONAL</strong>, correspondiente al dominio <strong>[</strong><strong>Acta:Dominio.Vehiculo</strong><strong>] </strong>en un plazo perentorio de 30 DÍAS. Caso contrario, se procederá a resolverse las actuaciones con las constancias obrantes en autos. Conste. -<strong>Firma: __________________________________________________</strong></p><p style="text-align:justify"><strong>Aclaración: ______________________________________________</strong></p><p style="text-align:justify"><strong>D.N.I. </strong><strong>Nº</strong><strong>: _______________________________________________</strong></p><p style="text-align:justify"><strong>Teléfono de contacto: _____________________________________</strong></p><p style="text-align:justify"><strong>Constituyo domicilio electrónico: ___________________________</strong></p>' WHERE codigo = 'NOTA_INTIMA_ACOMPANE_VTV';
UPDATE plantilla SET contenido_html = '<p style="text-align:right">Los Polvorines, [System:TEXTOFECHA]</p><p style="text-align:right"><strong>Ref. Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong></p><p style="text-align:right"><strong>Infractor: [</strong><strong>Acta:Titular</strong><strong>]</strong></p><p><strong>Al Depto. de </strong></p><p><strong>Licencias de Conducir de la </strong></p><p><strong>Municipalidad de ______________</strong></p><p><strong>S_________/__________D</strong></p><p style="text-align:justify"><strong>VIVODA MARÍA ELENA</strong>, en mi carácter de Directora de Faltas de la Municipalidad de Malvinas Argentinas, ubicada en la calle San Martín N° 2670 – Local 2, Puerta 1 “Galería Libertador” de la ciudad de Los Polvorines, partido de Malvinas Argentinas, provincia de Buenos Aires, tengo el agrado de dirigirme a Ud. en relación al acta de referencia, a efectos de informar que esta dirección no procederá a la restitución de la licencia de conducir N° <strong>[</strong><strong>Acta:Nro.Documento</strong><strong>] </strong>atento su vencimiento operó el día _________________ y el conductor fue detenido por el operativo de control de documentación el pasado día [Acta:Fecha], por lo que llevaba <strong>_______________ </strong>circulando en infracción. En consecuencia, el funcionario de tránsito procedió retención conforme lo normado en el Art. 72 de la Ley Nacional de Tránsito N° 24.449, adherida por la provincia de Buenos Aires con la Ley Provincial N° 13.927, cuerpo normativo que contiene la misma disposición en su Art. 37.</p><p style="text-align:justify">El texto referido expresamente dice: <strong>ARTICULO 72. — RETENCION PREVENTIVA</strong>. La autoridad de comprobación o aplicación debe retener, dando inmediato conocimiento a la autoridad de juzgamiento: (…) <strong>b) </strong>A las licencias habilitantes, cuando: <strong>1. </strong>Estuvieren vencidas.</p><p style="text-align:justify">Acompañado copia certificada de <strong>Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong> y <strong>licencia de conducir </strong><strong>N°</strong><strong> [</strong><strong>Acta:Nro.Documento</strong><strong>] </strong>expedida por la <strong>Municipalidad de _____ </strong>con <strong>fecha de otorgamiento ____________ </strong>y<strong> fecha de vencimiento _____________</strong>. -</p><p style="text-align:center"><strong>DF</strong></p><p style="text-align:center"><strong>Dra. María Elena </strong><strong>Vivoda</strong></p><p style="text-align:center"><strong>Directora de Faltas</strong></p><p style="text-align:center"><strong>Municipalidad de Malvinas Argentinas</strong></p>' WHERE codigo = 'NOTA_LICENCIA_VENCIDA';
UPDATE plantilla SET contenido_html = '<p style="text-align:right">Los Polvorines, [System:TEXTOFECHA]</p><p><strong>A la Sra. Juez de Faltas</strong></p><p><strong>de Trenque Lauquen</strong></p><p><strong>Dra. CICCONI, María Clara</strong></p><p><strong>S_________/_________D</strong></p><p style="text-align:justify"><strong>VIVODA MARÍA ELENA</strong>, en mi carácter de Directora de Faltas de la Municipalidad de Malvinas Argentinas, me dirijo a Ud. a efectos de poner en su conocimiento que esta Dirección carece de oficiales notificadores, utilizándose para los diligenciamientos de cédulas el servicio de correo privado, en consecuencia, la diligencia de las cédulas por Ud. enviadas no podrá ser efectivizada.</p><p style="text-align:justify">Sirva la presente de atenta nota de estilo. -</p><p style="text-align:center"><strong>DF</strong></p><p style="text-align:center"><strong>Dra. María Elena </strong><strong>Vivoda</strong></p><p style="text-align:center"><strong>Directora de Faltas</strong></p><p style="text-align:center"><strong>Municipalidad de Malvinas Argentinas</strong></p>' WHERE codigo = 'NOTA_NO_DILIGENCIA_CEDULAS';
UPDATE plantilla SET contenido_html = '<p style="text-align:center"><strong>Legajo </strong><strong>N°</strong><strong> [</strong><strong>Acta:Expediente</strong><strong>]</strong><strong>Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong></p><p style="text-align:right">Los Polvorines, [System:TEXTOFECHA]</p><p style="text-align:justify">En el día de la fecha, por medio de la presente, se notifica al <strong>Sr. [</strong><strong>Acta:Titular</strong><strong>], [</strong><strong>Acta:TipoDocumento</strong><strong>] </strong><strong>Nº</strong><strong> [</strong><strong>Acta:Nro.Documento</strong><strong>], DISPOSICIÓN DE LEVANTAMIENTO DE SECUESTRO </strong><strong>N°</strong><strong> ................................... </strong>de fecha [System:TEXTOFECHA] correspondiente al <strong>Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>] </strong>de fecha [Acta:Fecha] dictada por la Sra. Directora de Faltas de la Municipalidad de Malvinas Argentinas.</p><p style="text-align:justify">No siendo para más, previa lectura y ratificación de los datos consignados precedentemente, los comparecientes firman el presente de conformidad. Se cierra el acto.-</p><p style="text-align:justify"><strong>Firma: __________________________________________________</strong></p><p style="text-align:justify"><strong>Aclaración: ______________________________________________</strong></p><p style="text-align:justify"><strong>D.N.I. </strong><strong>Nº</strong><strong>: _______________________________________________</strong></p><p style="text-align:justify"><strong>Teléfono de contacto: _____________________________________</strong></p><p><strong>Constituyo domicilio electrónico: ___________________________</strong></p><p style="text-align:justify"><strong>Firma: __________________________________________________</strong></p><p style="text-align:justify"><strong>Aclaración: ______________________________________________</strong></p><p style="text-align:justify"><strong>D.N.I. </strong><strong>Nº</strong><strong>: _______________________________________________</strong></p><p style="text-align:justify"><strong>Teléfono de contacto: _____________________________________</strong></p><p><strong>Constituyo domicilio electrónico: ___________________________</strong></p>' WHERE codigo = 'NOTIFICA_LEVANTAMIENTO';
UPDATE plantilla SET contenido_html = '<p style="text-align:center"><strong><u>NOTIFICACIÓN DE SENTENCIA</u></strong></p><p><strong>Señor/a:</strong><strong>   </strong>[Acta:Titular]</p><p><strong>Legajo </strong><strong>N°</strong><strong> </strong><strong>   </strong>[Acta:Expediente]</p><p><strong>Domicilio:</strong><strong>   </strong>[Acta:Calle]   <strong>N°</strong>   [Acta:Nro.Puerta]</p><p><strong>Ciudad / Partido</strong><strong>:  </strong>[Acta:Localidad]  / [Acta:Partido]    <strong>Provincia: </strong>[Acta:Provincia.Infractor]</p><p><strong>Repartición Actuante:   </strong>SUBSCRETARÍA DE TRÁNSITO Y BROMATOLOGÍA</p><p style="text-align:justify">Se notifica a Ud. por la presente cédula que en el <strong>Acta de Infracción </strong><strong>Nº</strong><strong> [</strong><strong>Acta:Numero</strong><strong>] </strong>que tramita ante la Dirección de Faltas de la Municipalidad de Malvinas Argentinas, se ha dictado <strong>Sentencia </strong><strong>Nº</strong><strong>    </strong>cuya copia se adjunta. -</p><p style="text-align:center"><strong>QUEDA UD. DEBIDAMENTE NOTIFICADO/A.</strong></p><p style="text-align:center"><strong>Dra. María Elena </strong><strong>Vivoda</strong></p><p style="text-align:center"><strong>Directora de Faltas</strong></p><p style="text-align:center"><strong>Municipalidad de Malvinas Argentinas</strong></p>' WHERE codigo = 'NOTIFICACION_DE_FALLO_TRANSITO';
