UPDATE plantilla SET contenido_html = '<p style="text-align:center"><strong>Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong><strong>Legajo </strong><strong>N°</strong><strong> [</strong><strong>Acta:Expediente</strong><strong>]</strong></p><p style="text-align:justify">En este acto el <strong>Sr. [</strong><strong>Acta:Titular</strong><strong>]</strong>, <strong>DNI </strong><strong>N°</strong><strong> [</strong><strong>Acta:Nro.Documento</strong><strong>]</strong> se notifica por medio de la presente que en virtud de las infracciones que constan en el <strong>Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong>, de conformidad con lo establecido en el Art. 85 Inc. A de la Ley Nacional de Tránsito N° 24.449 y Art. 35 Inc. G de la Ley Provincial N° 13.927, cuenta con la posibilidad de acogerse al beneficio del pago voluntario, abonando la multa que corresponde al caso, con una reducción del <strong>CINCUENTA POR CIENTO (50%)</strong>, pudiendo hacer uso de este derecho dentro de los treinta (30) días corridos de recibida la presente notificación. Vencido el plazo sin que exista constancia de la utilización del beneficio del pago voluntario, de pago o allanamiento, tendrá un plazo de quince (15) días, contados a partir del día siguiente del vencimiento del plazo para el pago voluntario, a los efectos de formular descargo, ofrecer y producir la prueba de que intente valerme, pudiendo ser asistido por un letrado, todo ello bajo apercibimiento de ser declarado rebelde y de resolverse el Acta de Infracción con las constancias obrantes en la causa. -</p><p style="text-align:justify"><strong>Lugar y fecha: Los Polvorines, [</strong><strong>System:FECHA</strong><strong>]</strong></p><p style="text-align:justify"><strong>Firma: __________________________________________________</strong></p><p style="text-align:justify"><strong>Aclaración: ______________________________________________</strong></p><p style="text-align:justify"><strong>D.N.I. </strong><strong>Nº</strong><strong>: _______________________________________________</strong></p><p style="text-align:justify"><strong>Teléfono de contacto: _____________________________________</strong></p><p><strong>Constituyo domicilio electrónico: ___________________________</strong></p>' WHERE codigo = 'NOTIFICACION_EN_MESA_TRANSITO';
